//Continuous State Monitoring

// Declare a variable to hold the previous state and a timer reference
let previousState = context.get('previousState') || null;
let timer = context.get('timer') || null;

// Get the current input message
let currentState = msg.payload;

// Function to handle the continuous state
const sendContinuousState = () => {
    node.send({ payload: 'continuous state' });
};

if (currentState === previousState) {
    // If the state is the same as the previous one
    if (!timer) {
        // Start sending 'continuous state' messages every 2 seconds
        timer = setInterval(sendContinuousState, 2000);
        context.set('timer', timer);
    }
} else {
    // If the state has changed
    // Clear the existing timer if it exists
    if (timer) {
        clearInterval(timer);
        timer = null;
        context.set('timer', timer);
    }

    // Send 'state changed' message
    node.send({ payload: 'state changed' });
}

// Update the previous state
context.set('previousState', currentState);

return msg;

// Node-RED Function: Detection Duration Module

// Declare a variable to hold the state and timer references
let detectedPeriod = context.get('detectedPeriod') || 5; // Default detection period in seconds

let detectionStart = context.get('detectionStart') || null;
let detectionTimer = context.get('detectionTimer') || null;


// Get the current input message
let currentState = msg.payload;
let currentTime = Date.now();

// Function to handle sending the detected message
const sendDetected = () => {
    node.send({ payload: 'detected' });
};

if (currentState === 'detected') {
    if (!detectionStart) {
        // If detection starts, record the start time
        detectionStart = currentTime;
        context.set('detectionStart', detectionStart);
    } else if ((currentTime - detectionStart) / 1000 >= detectedPeriod) {
        // If detection period is met, send detected message
        sendDetected();
        detectionStart = null; // Reset start time after sending
        context.set('detectionStart', detectionStart);
    }
} else {
    // Reset detection start if state is not 'detected'
    detectionStart = null;
    context.set('detectionStart', detectionStart);
}

return null; // No message will pass through other than 'detected'

