// Define the distance range boundaries
const d1 = 3;
const d2 = 6;

// Function to calculate the distance between two points (xa, ya) and (xb, yb)
function calculateDistance(xa, ya, xb, yb) {
    const dx = xb - xa;
    const dy = yb - ya;
    return Math.sqrt(dx * dx + dy * dy);
}

// Get the input points from the message payload
