const ya = msg.payload.ya;
const xb = msg.payload.xb;
const yb = msg.payload.yb;

// Calculate the distance
const distance = calculateDistance(xa, ya, xb, yb);

// Check if the distance is within the specified range
if (distance >= d1 && distance <= d2) {
    msg.payload.result = 'detected';
} else {
    msg.payload.result = 'out of range';
}

// Include the calculated distance in the message payload
msg.payload.distance = distance;

// Return the message
return msg;

